impl RunSearchUseCase {
    pub fn new(uow_factory: Box<dyn RunSearchUnitOfWorkFactoryTrait>) -> Self {
        RunSearchUseCase { uow_factory }
    }

    pub fn execute(&mut self, dto: &RunSearchDto) -> Result<RunSearchResultDto> {
        let mut uow = self.uow_factory.create();
        uow.begin_transaction()?;

        // Search the caller-named Work's own WorkInfo — it owns the Search.
        // (`load_work` / `new_work` create both Work and WorkInfo eagerly.)
        let work_id = dto.work_id as EntityId;
        let work_info: WorkInfo = uow
            .get_all_work_info()?
            .into_iter()
            .find(|wi| wi.work == Some(work_id))
            .ok_or_else(|| anyhow!("work {work_id} is not open"))?;
        let search_id = work_info.search;
        let search: Search = uow
            .get_search(&search_id)?
            .ok_or_else(|| anyhow!("run_search: WorkInfo {search_id} has no Search"))?;

        // Drop the previous result set in ONE call. `Search`/`SearchResult` are
        // `undoable: false`, so nothing snapshots them and this genuinely frees the
        // rows rather than retaining them for an undo that can never happen.
        let previous: Vec<EntityId> =
            uow.get_search_relationship(&search_id, &SearchRelationshipField::Results)?;
        if !previous.is_empty() {
            uow.remove_search_result_multi(&previous)?;
        }

        let (rows, truncated) = if dto.query.is_empty() {
            (Vec::new(), false)
        } else {
            let corpus = self.collect_corpus(&mut uow, dto)?;
            Self::scan(&corpus, dto)
        };

        let match_count: u64 = rows.iter().map(|r| r.occurrence_count).sum();
        let item_count = {
            let mut ids: Vec<EntityId> = rows.iter().map(|r| r.binder_item_id).collect();
            ids.sort_unstable();
            ids.dedup();
            ids.len() as u64
        };

        // Create the new rows in ONE call, then attach them to the Search in one
        // relationship write. Two store writes for the whole result set, whether it
        // holds three rows or every field in the manuscript — which is what makes
        // `RESULT_CAP` affordable at its current size.
        // `create_multi` attaches the rows to their owner as it creates them
        // (`index = -1` appends), so the whole result set lands in ONE store write —
        // no per-row create, no separate relationship write.
        let created: Vec<SearchResult> = if rows.is_empty() {
            Vec::new()
        } else {
            uow.create_search_result_multi(&rows, search_id, -1)?
        };
        let created_ids: Vec<EntityId> = created.iter().map(|r| r.id).collect();

        // Mirror the query + flags onto the Search so the entity is an honest record
        // of what produced these rows (the UI reads its own signals, but a stale
        // Search next to a fresh result set would be a lie).
        let updated = Search {
            query: dto.query.clone(),
            case_sensitive: dto.case_sensitive,
            whole_word: dto.whole_word,
            diacritic_sensitive: dto.diacritic_sensitive,
            facets: dto.facets.clone(),
            search_body: dto.search_body,
            search_titles: dto.search_titles,
            search_synopsis: dto.search_synopsis,
            search_labels: dto.search_labels,
            include_trashed: dto.include_trashed,
            truncated,
            ..search
        };
        uow.update_search(&updated)?;

        uow.commit()?;

        // ONE event for the whole search. The UI's SearchResultsModel subscribes to
        // this origin alone — not to the per-entity Created/Removed events — so it
        // rebuilds once per search regardless of how many rows changed.
        uow.publish_run_search_event(created_ids, None);

        Ok(RunSearchResultDto {
            match_count,
            item_count,
            truncated,
        })
    }

    /// Walk Work → Binders → BinderItems → Contents and flatten every searchable
    /// field into one list, each carrying the language it is written in.
    fn collect_corpus(
        &self,
        uow: &mut Box<dyn RunSearchUnitOfWorkTrait>,
        dto: &RunSearchDto,
    ) -> Result<Vec<Field>> {
        let work_id = dto.work_id as EntityId;
        let work: Work = uow
            .get_all_work()?
            .into_iter()
            .find(|w| w.id == work_id)
            .ok_or_else(|| anyhow!("work {work_id} is not open"))?;

        // Resolved ONCE for the whole search, not re-parsed per item.
        let wanted = Self::wanted_facets(dto);

        let mut fields = Vec::new();
        // Which item each `Content` row belongs to, filled in as the walk goes. The
        // comment pass needs it and there is no reverse pointer from a `Content` to
        // its `BinderItem` — building it here costs nothing, since the walk is
        // already visiting every row it would have to search for.
        let mut owners: HashMap<EntityId, ContentOwner> = HashMap::new();
        let binder_ids = uow.get_work_relationship(&work.id, &WorkRelationshipField::Binders)?;
        for binder in uow.get_binder_multi(&binder_ids)?.into_iter().flatten() {
            let item_ids =
                uow.get_binder_relationship(&binder.id, &BinderRelationshipField::BinderItems)?;
            let items: Vec<BinderItem> = uow
                .get_binder_item_multi(&item_ids)?
                .into_iter()
                .flatten()
                .collect();

            // The language chain, resolved over the binder's ordered stream — the "nearest
            // Book" of an item is simply the most recent `Book` before it, because the tree
            // is organisational only and book structure is a state machine over the flat
            // stream. Done once per binder rather than per item, and through the same
            // function `replace_in_project` uses, so a rename cannot find a word under one
            // set of rules and rewrite it under another.
            let mut tags: HashMap<EntityId, Vec<String>> = HashMap::new();
            crate::language::tags_in_binder(&work.dict_language, &items, &mut tags);

            for item in &items {
                // A missing entry means "no tag anywhere up the chain" — untailored, which
                // is also what a malformed tag resolves to. Never an error: it comes from a
                // writer's project settings, and a typo there must not break searching.
                // `dict_language` is a tag *list* now; folding is monolingual, so fold under
                // the primary (first) tag — the language the scene is chiefly written in.
                let locale = tags.get(&item.id).map_or(FoldLocale::Root, |tag| {
                    FoldLocale::from_tag(crate::language::primary(tag))
                });
                self.item_fields(
                    uow,
                    item,
                    dto,
                    locale,
                    wanted.as_deref(),
                    &mut fields,
                    &mut owners,
                )?;
            }
        }
        if dto.search_comments {
            self.comment_fields(uow, dto, &work, &owners, &mut fields)?;
        }
        // Governed by "body text", not by the comments toggle: a footnote is part
        // of the manuscript a reader receives, the way an epigraph is, so a writer
        // searching the book expects to find one. It reports its own match field
        // regardless, because a replace rewrites a different table.
        if dto.search_body {
            self.footnote_fields(uow, dto, &work, &owners, &mut fields)?;
        }
        Ok(fields)
    }

    /// Footnote bodies, scanned in their own walk.
    ///
    /// Footnotes hang off `Work`, not off `Content`, so `field_of_role` never
    /// answers for them — the same reason comments get their own pass. Unlike a
    /// comment, though, the text is **Djot**: a note carries italics and a
    /// citation like any other prose, so it goes through the same parse-and-fold
    /// cache scene text does. `FieldText::Plain` is for markup-free strings, and
    /// using it here would let a search for a word match the middle of a
    /// formatting marker.
    ///
    /// `footnote.content` below is trusted at face value — this walk does not
    /// re-derive which item a note "really" belongs to. That is safe only because
    /// `binder_item_management`'s `split_scene`/`merge_two_scenes` keep it correctly
    /// reparented whenever they relocate the `Content` row a note's citation lives in
    /// (see `binder_item_management::footnote_reanchor`); before that existed, this
    /// field could point at a scene the citation had already moved out of, and a
    /// search hit would silently name the wrong item. Notice this **cannot** be caught
    /// by testing the editor or the Footnotes dock: `skribisto_model::footnote_numbering`
    /// (which drives both) never reads `Footnote.content` at all — it re-derives a
    /// note's placement by scanning live prose on every pass, precisely so a stale
    /// stored pointer like this one could never affect what the writer sees while
    /// editing. Only a reader that trusts the stored anchor — this one, and
    /// `progress_management::count_words` — was ever exposed to the drift.
    fn footnote_fields(
        &self,
        uow: &mut Box<dyn RunSearchUnitOfWorkTrait>,
        dto: &RunSearchDto,
        work: &Work,
        owners: &HashMap<EntityId, ContentOwner>,
        out: &mut Vec<Field>,
    ) -> Result<()> {
        let ids = uow.get_work_relationship(&work.id, &WorkRelationshipField::Footnotes)?;
        for footnote in uow.get_footnote_multi(&ids)?.into_iter().flatten() {
            let owner = match footnote.content {
                Some(content_id) => match owners.get(&content_id) {
                    Some(o) => Some(o),
                    // Anchored to a row this search did not walk — out of scope.
                    None => continue,
                },
                None => None,
            };
            let (item_id, item_title, trashed, locale) = match owner {
                Some(o) => (o.item_id, o.item_title.clone(), o.trashed, o.locale),
                None => (0, String::new(), false, FoldLocale::Root),
            };
            if trashed && !dto.include_trashed {
                continue;
            }
            if footnote.body.is_empty() {
                continue;
            }
            let fold_spec = MatchOptions {
                case_sensitive: dto.case_sensitive,
                diacritic_sensitive: dto.diacritic_sensitive,
                whole_word: dto.whole_word,
                locale,
            }
            .fold_spec();
            let corpus = corpus_cache::corpus_for(&footnote.body, &fold_spec);
            if corpus.source().is_empty() {
                continue;
            }
            out.push(Field {
                item_id,
                item_title,
                match_field: MatchField::Footnote,
                text: FieldText::Prose(corpus),
                trashed,
                locale,
                comment_id: 0,
                reply_id: 0,
                footnote_id: footnote.id,
            });
        }
        Ok(())
    }

    /// Comment threads and their replies, as searchable fields.
    ///
    /// A separate walk because comments hang off **`Work`**, not off `Content`: the
    /// item loop above never reaches them. What it does leave behind is `owners` —
    /// which item each `Content` row belongs to — and that is what lets a comment hit
    /// say *"on Scene 1"* rather than just quoting itself.
    ///
    /// Three cases for a thread's anchor, and they are deliberately not the same:
    ///
    /// * **Anchored to a row we walked.** It inherits that item's title, trashed flag
    ///   and language, so a comment on a French scene folds under French rules like
    ///   the scene does.
    /// * **Anchored to a row we skipped** — the item was facet-filtered, trashed and
    ///   excluded, or the content was deactivated. Skipped too: the item is out of
    ///   scope for this search, so its annotations are as well.
    /// * **Anchored to nothing at all** — an orphan whose text was deleted, or a
    ///   `Document`-kind thread. Kept, with no item. This follows `item_fields`'
    ///   "never hide what we cannot name": an orphaned comment is precisely the one a
    ///   writer needs to find in order to deal with it, and search may be the only
    ///   surface that can still reach it.
    fn comment_fields(
        &self,
        uow: &mut Box<dyn RunSearchUnitOfWorkTrait>,
        dto: &RunSearchDto,
        work: &Work,
        owners: &HashMap<EntityId, ContentOwner>,
        out: &mut Vec<Field>,
    ) -> Result<()> {
        let comment_ids = uow.get_work_relationship(&work.id, &WorkRelationshipField::Comments)?;
        for comment in uow.get_comment_multi(&comment_ids)?.into_iter().flatten() {
            let owner = match comment.content {
                Some(content_id) => match owners.get(&content_id) {
                    Some(o) => Some(o),
                    // Anchored to a row this search did not walk — out of scope.
                    None => continue,
                },
                None => None,
            };
            let (item_id, item_title, trashed, locale) = match owner {
                Some(o) => (o.item_id, o.item_title.clone(), o.trashed, o.locale),
                // An orphan belongs to no item. `FoldLocale::Root` rather than the
                // Work's own tag: with no anchor there is no scene whose language
                // this could claim to be, and Root is the untailored fold the rest of
                // this file already uses for "no tag anywhere up the chain".
                None => (0, String::new(), false, FoldLocale::Root),
            };
            if trashed && !dto.include_trashed {
                continue;
            }
            if !comment.body.is_empty() {
                out.push(Field {
                    item_id,
                    item_title: item_title.clone(),
                    match_field: MatchField::Comment,
                    text: FieldText::Plain(comment.body.clone()),
                    trashed,
                    locale,
                    comment_id: comment.id,
                    reply_id: 0,
                    footnote_id: 0,
                });
            }
            let reply_ids =
                uow.get_comment_relationship(&comment.id, &CommentRelationshipField::Replies)?;
            for reply in uow
                .get_comment_reply_multi(&reply_ids)?
                .into_iter()
                .flatten()
            {
                if reply.body.is_empty() {
                    continue;
                }
                out.push(Field {
                    item_id,
                    item_title: item_title.clone(),
                    match_field: MatchField::CommentReply,
                    text: FieldText::Plain(reply.body.clone()),
                    trashed,
                    locale,
                    // The THREAD in both cases — that is what the margin and the docks
                    // reveal — plus this reply's own row, which is what a replace edits.
                    comment_id: comment.id,
                    reply_id: reply.id,
                    footnote_id: 0,
                });
            }
        }
        Ok(())
    }

    /// Which facet chips the writer actually ticked. `None` means **no filter**.
    ///
    /// Two ways to get `None`, and they mean the same thing to a reader:
    ///
    ///   * **Nothing ticked.** A filter with no selection does not select nothing — it selects
    ///     everything. Get that backwards and the search panel opens showing zero results and
    ///     the writer concludes it is broken.
    ///   * **Nothing ticked that we recognise.** A code naming no facet can only come from a
    ///     `search.toml` written by a version whose codes differed. Dropping such codes one by
    ///     one is not enough: if they are ALL unknown, the list is still non-empty, filtering
    ///     still runs, and it matches nothing — so an upgrade would silently leave someone
    ///     unable to find their own prose. An unrecognisable filter is no filter.
    fn wanted_facets(dto: &RunSearchDto) -> Option<Vec<SearchFacet>> {
        if dto.facets.is_empty() {
            return None;
        }
        let resolved: Vec<SearchFacet> = dto
            .facets
            .iter()
            // A negative code cannot name a facet; the `as u64` wrap makes it a huge number,
            // which `from_code` rejects like any other unknown.
            .filter_map(|&code| SearchFacet::from_code(code as u64))
            .collect();
        (!resolved.is_empty()).then_some(resolved)
    }

    /// The searchable fields of one item, filtered by the requested scopes.
    #[allow(clippy::too_many_arguments)]
    fn item_fields(
        &self,
        uow: &mut Box<dyn RunSearchUnitOfWorkTrait>,
        item: &BinderItem,
        dto: &RunSearchDto,
        locale: FoldLocale,
        facets: Option<&[SearchFacet]>,
        out: &mut Vec<Field>,
        owners: &mut HashMap<EntityId, ContentOwner>,
    ) -> Result<()> {
        // How this item's prose folds. `whole_word` is deliberately absent: it decides which
        // matches survive, not how a character folds, so one cached fold answers both kinds
        // of query and ticking the checkbox costs nothing.
        let fold_spec = MatchOptions {
            case_sensitive: dto.case_sensitive,
            diacritic_sensitive: dto.diacritic_sensitive,
            whole_word: dto.whole_word,
            locale,
        }
        .fold_spec();

        let trashed = !item.activated;
        if trashed && !dto.include_trashed {
            return Ok(());
        }

        if let Some(wanted) = facets {
            match search_facet_of(&item.role, &item.sub_role) {
                Some(f) if wanted.contains(&f) => {}
                Some(_) => return Ok(()),
                // A combination the matrix does not contain — which means it cannot exist, and
                // yet here it is (the Plume importer and the legacy upgrader both synthesise
                // sub_roles). **Never hide what we cannot name.** Filtering it out would make
                // the item findable with no chips ticked and invisible with any chip ticked,
                // which reads as the filter being broken rather than the item being malformed
                // — and leaves the writer no way to reach the thing and fix it.
                None => {}
            }
        }

        let title = item.title.clone();

        // Title and label live on the ITEM, as plain strings — not as Content rows.
        // Only Book/Part/Chapter have title Content at all, so a uniform "parse the
        // title Content" walk would silently return nothing for every Scene, Note and
        // Text in the manuscript. Read them from the item.
        if dto.search_titles && !item.title.is_empty() {
            out.push(Field {
                item_id: item.id,
                item_title: title.clone(),
                match_field: MatchField::Title,
                text: FieldText::Plain(item.title.clone()),
                trashed,
                locale,
                comment_id: 0,
                reply_id: 0,
                footnote_id: 0,
            });
        }
        if dto.search_labels && !item.label.is_empty() {
            out.push(Field {
                item_id: item.id,
                item_title: title.clone(),
                match_field: MatchField::Label,
                text: FieldText::Plain(item.label.clone()),
                trashed,
                locale,
                comment_id: 0,
                reply_id: 0,
                footnote_id: 0,
            });
        }

        // Comments need this walk too, even with every prose scope off: it is the only
        // place that learns which item a `Content` row belongs to, and a comment hit
        // has to be able to name its scene.
        if !dto.search_body && !dto.search_synopsis && !dto.search_comments {
            return Ok(());
        }
        let content_ids =
            uow.get_binder_item_relationship(&item.id, &BinderItemRelationshipField::Contents)?;
        for content in uow.get_content_multi(&content_ids)?.into_iter().flatten() {
            if !content.activated {
                continue;
            }
            // Recorded before the emptiness and role checks below, and for every role:
            // a comment can be anchored to a scene whose prose has since been emptied,
            // or to a synopsis while only the body is being searched, and in both cases
            // the thread still belongs to this item and must be able to say so.
            owners.insert(
                content.id,
                ContentOwner {
                    item_id: item.id,
                    item_title: title.clone(),
                    trashed,
                    locale,
                },
            );
            if content.data.is_empty() {
                continue;
            }
            // Which field this row reports is `match_field`'s business, not this loop's
            // — Replace All resolves a result back to its row through the same mapping,
            // and the two drifting apart is how a hit gets rewritten into the wrong
            // document. Which *toggle* governs it stays here: an epigraph is searched
            // when the writer ticks "body text", because quoted matter is part of the
            // manuscript, even though it reports `MatchField::Epigraph`.
            let Some(field) = crate::match_field::field_of_role(&content.role) else {
                continue;
            };
            let wanted = match field {
                MatchField::Body | MatchField::Epigraph => dto.search_body,
                MatchField::Synopsis => dto.search_synopsis,
                // Not reachable from a `Content` row: titles and labels live on the
                // `BinderItem`, comments on their own entities, and all four are scanned
                // in their own passes. `field_of_role` never returns them, and the
                // exhaustive match is what keeps that true as the enum grows.
                MatchField::Title
                | MatchField::Label
                | MatchField::Comment
                | MatchField::CommentReply
                | MatchField::Footnote => false,
            };
            if !wanted {
                continue;
            }
            // `Content.data` is **Djot**, i.e. markup. Searching it directly would match
            // text the writer never wrote and cannot see: `http` inside a link's URL, `*`
            // on an emphasis marker, `#` on a heading. Worse, an occurrence count taken
            // from the markup does not agree with what `replace_in_project` re-derives
            // inside the parsed document — so its "the text moved under me, skip this
            // field" guard would fire on perfectly good rows and silently refuse to rename
            // them.
            //
            // `djot_to_plain_text` extracts the prose without importing the document (27x
            // cheaper than a full import, which matters when a keystroke rescans the whole
            // manuscript) and is pinned upstream as being *exactly* the text the document
            // itself searches. So a count taken here survives a replace performed there.
            //
            // Both the parse and the fold go through the CACHE. They are the whole cost of a
            // search — measured over a 300k-word manuscript, 33 ms to parse and 14 ms to
            // fold, against 16 ms to actually scan — and neither changes between one
            // keystroke and the next. The cache is content-addressed, so there is nothing to
            // invalidate: edited prose is a different key.
            let corpus = corpus_cache::corpus_for(&content.data, &fold_spec);
            if corpus.source().is_empty() {
                continue;
            }
            out.push(Field {
                item_id: item.id,
                item_title: title.clone(),
                match_field: field,
                text: FieldText::Prose(corpus),
                trashed,
                locale,
                comment_id: 0,
                reply_id: 0,
                footnote_id: 0,
            });
        }
        Ok(())
    }

    /// Match every field, one row per field that hits. Stops at `RESULT_CAP`.
    fn scan(corpus: &[Field], dto: &RunSearchDto) -> (Vec<SearchResult>, bool) {
        let mut rows = Vec::new();
        for field in corpus {
            // The SHARED matcher's options — the same ones the editor's own find uses, so a
            // writer can never be shown a result set the editor disagrees with.
            //
            // Built **per field**, because the locale is per field. The user's two toggles
            // stay global: the language decides *how* to fold, never *whether* to, or the
            // same checkbox would mean different things in different chapters of one book.
            //
            // Both `whole_word` and `diacritic_sensitive` must actually reach the matcher —
            // a toggle that silently does nothing is worse than a missing one: the writer
            // believes the search was narrowed when it was not.
            let options = MatchOptions {
                case_sensitive: dto.case_sensitive,
                diacritic_sensitive: dto.diacritic_sensitive,
                whole_word: dto.whole_word,
                locale: field.locale,
            };
            let hits = match &field.text {
                // A title or a label: a dozen characters. Folded on the spot.
                FieldText::Plain(s) => crate::matching::occurrences(s, &dto.query, options),
                // A scene's prose: already folded, once, and kept between keystrokes. Only the
                // scan is left — which is the part that actually depends on what was typed.
                FieldText::Prose(corpus) => corpus
                    .find_all(&dto.query, options.whole_word)
                    .into_iter()
                    .map(|m| (m.char_start, m.char_len))
                    .collect(),
            };
            let Some(&(first, first_len)) = hits.first() else {
                continue;
            };
            if rows.len() >= RESULT_CAP {
                return (rows, true);
            }
            let (before, matched, after) = Self::snippet(field.text.as_str(), first, first_len);
            rows.push(SearchResult {
                binder_item_id: field.item_id,
                item_title: field.item_title.clone(),
                match_field: field.match_field.clone(),
                occurrence_count: hits.len() as u64,
                snippet_before: before,
                snippet_match: matched,
                snippet_after: after,
                trashed: field.trashed,
                comment_id: field.comment_id,
                reply_id: field.reply_id,
                // Without this the row reaches Replace All naming note 0, and the
                // rewrite silently finds nothing to write to. `..Default::default()`
                // is why it compiled: an omitted id is a plausible zero, not an
                // error, so only the dead-code warning on `Field::footnote_id` ever
                // said the value was being computed and thrown away.
                footnote_id: field.footnote_id,
                ..Default::default()
            });
        }
        (rows, false)
    }

    /// `SNIPPET_CONTEXT` chars either side of the match, on char boundaries.
    ///
    /// Walks `char_indices` rather than collecting the field into a `Vec<char>`. The
    /// difference is not cosmetic: this runs for every matching row, up to `RESULT_CAP`, and a
    /// manuscript of long scenes would otherwise materialise the *whole scene* at four bytes
    /// per char — tens of megabytes of transient garbage, on the UI thread — to produce a
    /// snippet of a couple of hundred characters.
    fn snippet(text: &str, char_start: usize, char_len: usize) -> (String, String, String) {
        let end = char_start + char_len;
        let from = char_start.saturating_sub(SNIPPET_CONTEXT);
        let to = end + SNIPPET_CONTEXT;

        // One pass: the byte offset of each of the four char positions that bound the three
        // pieces. Any that lies past the end of the text simply never gets set, and falls back
        // to the end — which is what `.min(len)` did before, without the allocation.
        let (mut b_from, mut b_start, mut b_end, mut b_to) = (None, None, None, None);
        for (i, (byte, _)) in text.char_indices().enumerate() {
            if i == from {
                b_from = Some(byte);
            }
            if i == char_start {
                b_start = Some(byte);
            }
            if i == end {
                b_end = Some(byte);
            }
            if i == to {
                b_to = Some(byte);
                break;
            }
        }
        let len = text.len();
        let (b_from, b_start) = (b_from.unwrap_or(len), b_start.unwrap_or(len));
        let (b_end, b_to) = (b_end.unwrap_or(len), b_to.unwrap_or(len));

        (
            text[b_from..b_start].to_string(),
            text[b_start..b_end].to_string(),
            text[b_end..b_to].to_string(),
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The snippet is cut on **char** boundaries, from text that is full of multi-byte chars —
    /// slicing it by byte would panic in the middle of an `é`.
    #[test]
    fn a_snippet_is_cut_on_char_boundaries() {
        let text = "Aurélien traversa la forêt où l'ombre s'étirait.";
        let hit = text.chars().collect::<Vec<_>>();
        let start = 21; // "forêt"
        assert_eq!(hit[start..start + 5].iter().collect::<String>(), "forêt");

        let (before, matched, after) = RunSearchUseCase::snippet(text, start, 5);
        assert_eq!(matched, "forêt");
        assert_eq!(before, "Aurélien traversa la ");
        assert_eq!(after, " où l'ombre s'étirait.");
        assert_eq!(
            format!("{before}{matched}{after}"),
            text,
            "the three pieces must reassemble the text they came from"
        );
    }

    /// A match at the very start and at the very end — the two places an off-by-one in the
    /// byte-offset walk would show up as a panic or a truncated snippet.
    #[test]
    fn a_snippet_at_either_edge_of_the_text() {
        let text = "Élena rentra chez ellé";

        let (before, matched, after) = RunSearchUseCase::snippet(text, 0, 5);
        assert_eq!(before, "");
        assert_eq!(matched, "Élena");
        assert_eq!(after, " rentra chez ellé");

        let n = text.chars().count();
        let (before, matched, after) = RunSearchUseCase::snippet(text, n - 4, 4);
        assert_eq!(matched, "ellé");
        assert_eq!(after, "", "nothing follows the last char");
        assert_eq!(before, "Élena rentra chez ");
    }

    /// Context is clamped to `SNIPPET_CONTEXT` chars either side, not bytes — so an accented
    /// scene does not get a shorter snippet than an ASCII one.
    #[test]
    fn a_snippet_is_clamped_to_the_context_in_chars() {
        let text = format!("{}CIBLE{}", "é".repeat(200), "à".repeat(200));
        let (before, matched, after) = RunSearchUseCase::snippet(&text, 200, 5);
        assert_eq!(matched, "CIBLE");
        assert_eq!(before.chars().count(), SNIPPET_CONTEXT);
        assert_eq!(after.chars().count(), SNIPPET_CONTEXT);
    }

    /// The whole text is shorter than the context window: take what there is, and do not run
    /// off the end.
    #[test]
    fn a_snippet_of_a_text_shorter_than_its_context() {
        let (before, matched, after) = RunSearchUseCase::snippet("où", 0, 2);
        assert_eq!(
            (before.as_str(), matched.as_str(), after.as_str()),
            ("", "où", "")
        );
    }
}
